import json
import sys
from datetime import datetime, timezone

def parse_ts(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(timezone.utc)

source_ip = sys.argv[1]
start = parse_ts(sys.argv[2])
end = parse_ts(sys.argv[3])
path = sys.argv[4]

selected = []
with open(path, encoding="utf-8") as fh:
    for line in fh:
        if not line.strip():
            continue
        event = json.loads(line)
        ts = parse_ts(event["timestamp"])
        if start <= ts <= end and event.get("source_ip") == source_ip:
            selected.append((ts, event))

for ts, event in sorted(selected):
    print(ts.isoformat(), event.get("event_type"), event.get("user"),
          event.get("host"), event.get("process_name"), event.get("result"))

from collections import defaultdict
from datetime import datetime, timedelta

events = [
    {"ts": "2026-09-07T12:00:00", "source_ip": "192.0.2.50", "user": "a", "result": "failure"},
    {"ts": "2026-09-07T12:01:00", "source_ip": "192.0.2.50", "user": "b", "result": "failure"},
    {"ts": "2026-09-07T12:02:00", "source_ip": "192.0.2.50", "user": "c", "result": "failure"},
    {"ts": "2026-09-07T12:03:00", "source_ip": "192.0.2.50", "user": "d", "result": "failure"},
    {"ts": "2026-09-07T12:20:00", "source_ip": "192.0.2.60", "user": "a", "result": "failure"},
]
approved_scanners = {"192.0.2.60"}
window = timedelta(minutes=10)

failures = [e for e in events if e["result"] == "failure" and e["source_ip"] not in approved_scanners]
for source in sorted({e["source_ip"] for e in failures}):
    source_events = sorted(
        (e for e in failures if e["source_ip"] == source),
        key=lambda e: datetime.fromisoformat(e["ts"])
    )
    for i, start_event in enumerate(source_events):
        start = datetime.fromisoformat(start_event["ts"])
        users = {
            e["user"] for e in source_events[i:]
            if datetime.fromisoformat(e["ts"]) <= start + window
        }
        if len(users) >= 4:
            print("ALERT", source, "distinct_users=", len(users))
            break
